import React from "react";
import { interpolateColors, useCurrentFrame } from "remotion";
import { Character } from "../characters/Character";
import type { Outfit, Person, Pose } from "../characters/types";

/*
 * Small helpers shared by the wedding-day scenes (DayTitle → Reception):
 * scene-space SVG wrapper, character placement, local↔scene mapping and a 2-bone arm IK
 * so hands can hold garlands, sehra strands, glasses and dhol sticks exactly.
 */

export type Pt = [number, number];

export const SVG: React.FC<{ children: React.ReactNode; w?: number; h?: number; x?: number; y?: number; style?: React.CSSProperties }> = ({
  children,
  w = 1080,
  h = 1920,
  x = 0,
  y = 0,
  style,
}) => (
  <svg
    width={w}
    height={h}
    viewBox={`${x} ${y} ${w} ${h}`}
    style={{ position: "absolute", left: x, top: y, overflow: "visible", ...style }}
  >
    {children}
  </svg>
);

/** A placed figure: centre x, feet y, drawn height, and the person's own scale. */
export type Fig = { cx: number; feet: number; h: number; ps: number; female: boolean };
export const fig = (p: Person, cx: number, feet: number, h: number): Fig => ({ cx, feet, h, ps: p.scale, female: p.face === "female" });

const left = (f: Fig) => f.cx - 0.2 * f.h;
const top = (f: Fig) => f.feet - 0.956 * f.h;

/** Character-local (400×1000 box, before person scale) → scene coordinates. */
export const toScene = (f: Fig, lx: number, ly: number): Pt => {
  const k = f.h / 1000;
  return [left(f) + (200 + (lx - 200) * f.ps) * k, top(f) + (956 + (ly - 956) * f.ps) * k];
};
/** Scene → character-local. */
export const toLocal = (f: Fig, sx: number, sy: number): Pt => {
  const k = f.h / 1000;
  return [200 + ((sx - left(f)) / k - 200) / f.ps, 956 + ((sy - top(f)) / k - 956) / f.ps];
};

/** Place a Character at a Fig. */
export const Figure: React.FC<{
  f: Fig;
  person: Person;
  outfit: Outfit;
  pose?: Partial<Pose>;
  sehra?: number;
  style?: React.CSSProperties;
  svgStyle?: React.CSSProperties;
}> = ({ f, person, outfit, pose, sehra, style, svgStyle }) => (
  <div style={{ position: "absolute", left: left(f), top: top(f), width: 0.4 * f.h, height: f.h, ...style }}>
    <Character person={person} outfit={outfit} height={f.h} pose={pose} sehra={sehra} style={svgStyle} />
  </div>
);

const ARM = {
  male: { l: [132, 238] as Pt, r: [268, 238] as Pt, U: 150, F: 158 },
  female: { l: [148, 238] as Pt, r: [252, 238] as Pt, U: 140, F: 149 },
};

const DEG = 180 / Math.PI;
/** Unit direction of an arm segment rotated by `a` degrees (0 = hanging straight down). */
const dir = (a: number): Pt => [-Math.sin(a / DEG), Math.cos(a / DEG)];

/** Hand centre (scene space) for a given shoulder/elbow pair. */
export const handAt = (f: Fig, side: "l" | "r", shoulder: number, elbow: number): Pt => {
  const a = f.female ? ARM.female : ARM.male;
  const s = side === "l" ? a.l : a.r;
  const d1 = dir(shoulder);
  const d2 = dir(shoulder + elbow);
  return toScene(f, s[0] + a.U * d1[0] + a.F * d2[0], s[1] + a.U * d1[1] + a.F * d2[1]);
};

/** Shoulder point in scene space. */
export const shoulderAt = (f: Fig, side: "l" | "r"): Pt => {
  const a = f.female ? ARM.female : ARM.male;
  const s = side === "l" ? a.l : a.r;
  return toScene(f, s[0], s[1]);
};

/**
 * 2-bone IK: shoulder & elbow angles that put the hand centre on `target` (scene space).
 * `bend` picks the elbow direction (-1 or 1). Unreachable targets straighten the arm toward them.
 */
export const reach = (f: Fig, side: "l" | "r", target: Pt, bend: 1 | -1 = -1): { shoulder: number; elbow: number } => {
  const a = f.female ? ARM.female : ARM.male;
  const s = side === "l" ? a.l : a.r;
  const [tx, ty] = toLocal(f, target[0], target[1]);
  const dx = tx - s[0];
  const dy = ty - s[1];
  const raw = Math.hypot(dx, dy);
  const D = Math.min(a.U + a.F - 0.5, Math.max(Math.abs(a.U - a.F) + 1, raw));
  const phi = Math.atan2(-dx / raw, dy / raw) * DEG;
  const alpha = Math.acos(Math.min(1, Math.max(-1, (a.U * a.U + D * D - a.F * a.F) / (2 * a.U * D)))) * DEG;
  const beta = Math.acos(Math.min(1, Math.max(-1, (a.U * a.U + a.F * a.F - D * D) / (2 * a.U * a.F)))) * DEG;
  return bend === -1 ? { shoulder: phi + alpha, elbow: -(180 - beta) } : { shoulder: phi - alpha, elbow: 180 - beta };
};

/** Pose object for both arms reaching targets (l/r shoulder & elbow). */
export const reachPose = (f: Fig, lt: Pt | null, rt: Pt | null, lBend: 1 | -1 = -1, rBend: 1 | -1 = 1): Partial<Pose> => {
  const out: Partial<Pose> = {};
  if (lt) {
    const r = reach(f, "l", lt, lBend);
    out.lShoulder = r.shoulder;
    out.lElbow = r.elbow;
  }
  if (rt) {
    const r = reach(f, "r", rt, rBend);
    out.rShoulder = r.shoulder;
    out.rElbow = r.elbow;
  }
  return out;
};

export const lerpPt = (a: Pt, b: Pt, t: number): Pt => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];

/** Quadratic bezier point. */
export const qPt = (a: Pt, c: Pt, b: Pt, t: number): Pt => {
  const u = 1 - t;
  return [u * u * a[0] + 2 * u * t * c[0] + t * t * b[0], u * u * a[1] + 2 * u * t * c[1] + t * t * b[1]];
};

/** Blend a list of colour stops by t ∈ [0,1]. */
export const colorAt = (t: number, stops: string[]): string =>
  interpolateColors(
    t,
    stops.map((_, i) => i / (stops.length - 1)),
    stops,
  );

/** Hides its children until `from` (keeps staged typography from showing stray rules before it starts). */
export const Gate: React.FC<{ from: number; children: React.ReactNode }> = ({ from, children }) => {
  const frame = useCurrentFrame();
  return <div style={{ position: "absolute", inset: 0, opacity: frame >= from ? 1 : 0 }}>{children}</div>;
};
